COMMENT ON COLUMN merchant_payment_link.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_payment_link.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_payment_link.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_payment_link.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_merchant_payment_link_tenant ON merchant_payment_link (tenant_id, created_at);
CREATE INDEX ix_merchant_payment_link_merchant_id ON merchant_payment_link (merchant_id);
ALTER TABLE merchant_payment_link ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON merchant_payment_link USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_merchant_payment_link_touch BEFORE UPDATE ON merchant_payment_link FOR EACH ROW EXECUTE FUNCTION touch_row();

-- merchant_settlement: Periodic settlement of merchant collections net of fees and refunds
CREATE TABLE merchant_settlement (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  merchant_id                  uuid NOT NULL REFERENCES merchant(id),
  period_start                 date NOT NULL,
  period_end                   date NOT NULL,
  currency                     char(3) NOT NULL,
  payment_count                integer,
  gross_amount                 numeric(28,8),
  mdr_amount                   numeric(28,8),
  refund_amount                numeric(28,8),
  net_amount                   numeric(28,8),
  status                       varchar(40) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'CALCULATED', 'APPROVED', 'PAID', 'FAILED', 'REJECTED')),
  settlement_wallet_id         uuid,
  settlement_account_id        uuid,
  approved_by                  varchar(64),
  approved_at                  timestamptz,
  rejected_by                  varchar(64),
  rejection_reason             varchar(255),
  payment_id                   uuid,
  fee_wallet_transaction_id    uuid,
  wallet_transaction_id        uuid,
  paid_at                      timestamptz,
  failure_reason               varchar(255),
  report_document_id           uuid,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE merchant_settlement IS 'Periodic settlement of merchant collections net of fees and refunds';
COMMENT ON COLUMN merchant_settlement.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN merchant_settlement.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN merchant_settlement.created_at IS 'Creation time';
COMMENT ON COLUMN merchant_settlement.created_by IS 'Principal that created the row';
COMMENT ON COLUMN merchant_settlement.updated_at IS 'Last update time';
COMMENT ON COLUMN merchant_settlement.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN merchant_settlement.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN merchant_settlement.merchant_id IS 'Merchant';
COMMENT ON COLUMN merchant_settlement.period_start IS 'From';
COMMENT ON COLUMN merchant_settlement.period_end IS 'To (inclusive)';
COMMENT ON COLUMN merchant_settlement.currency IS 'Currency';
COMMENT ON COLUMN merchant_settlement.payment_count IS 'Payments included';
COMMENT ON COLUMN merchant_settlement.gross_amount IS 'Gross collections';
COMMENT ON COLUMN merchant_settlement.mdr_amount IS 'Merchant discount fees';
COMMENT ON COLUMN merchant_settlement.refund_amount IS 'Refunds';
COMMENT ON COLUMN merchant_settlement.net_amount IS 'Net payable';
COMMENT ON COLUMN merchant_settlement.status IS 'Status (REJECTED releases its payments for a new settlement)';
COMMENT ON COLUMN merchant_settlement.settlement_wallet_id IS 'Wallet the collections sit in';
COMMENT ON COLUMN merchant_settlement.settlement_account_id IS 'Bank account paid (empty = net stays in the wallet)';
COMMENT ON COLUMN merchant_settlement.approved_by IS 'Checker';
COMMENT ON COLUMN merchant_settlement.approved_at IS 'Approval time';
COMMENT ON COLUMN merchant_settlement.rejected_by IS 'Checker who rejected the settlement';
COMMENT ON COLUMN merchant_settlement.rejection_reason IS 'Why the settlement was rejected';
COMMENT ON COLUMN merchant_settlement.payment_id IS 'Bank payment when settled to bank';
COMMENT ON COLUMN merchant_settlement.fee_wallet_transaction_id IS 'MDR fee transaction';
COMMENT ON COLUMN merchant_settlement.wallet_transaction_id IS 'Settlement transaction to the bank account';
COMMENT ON COLUMN merchant_settlement.paid_at IS 'Payment time';
COMMENT ON COLUMN merchant_settlement.failure_reason IS 'Failure reason';
COMMENT ON COLUMN merchant_settlement.report_document_id IS 'Settlement report';
COMMENT ON COLUMN merchant_settlement.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_settlement.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_settlement.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_settlement.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_settlement.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_merchant_settlement_tenant ON merchant_settlement (tenant_id, created_at);
CREATE INDEX ix_merchant_settlement_merchant_id ON merchant_settlement (merchant_id);
CREATE INDEX ix_merchant_settlement_settlement_wallet_id ON merchant_settlement (settlement_wallet_id);
CREATE INDEX ix_merchant_settlement_settlement_account_id ON merchant_settlement (settlement_account_id);
CREATE INDEX ix_merchant_settlement_payment_id ON merchant_settlement (payment_id);
CREATE INDEX ix_merchant_settlement_fee_wallet_transaction_id ON merchant_settlement (fee_wallet_transaction_id);
CREATE INDEX ix_merchant_settlement_wallet_transaction_id ON merchant_settlement (wallet_transaction_id);
CREATE INDEX ix_merchant_settlement_report_document_id ON merchant_settlement (report_document_id);
ALTER TABLE merchant_settlement ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON merchant_settlement USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_merchant_settlement_touch BEFORE UPDATE ON merchant_settlement FOR EACH ROW EXECUTE FUNCTION touch_row();

-- merchant_refund: A full or partial refund of a merchant payment
CREATE TABLE merchant_refund (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  merchant_id                  uuid NOT NULL REFERENCES merchant(id),
  original_transaction_id      uuid NOT NULL,
  amount                       numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  reason                       varchar(255) NOT NULL,
  status                       varchar(40) NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED', 'PENDING_BANK_APPROVAL', 'APPROVED', 'COMPLETED', 'REJECTED', 'FAILED')),
  merchant_approved_by         varchar(64),
  merchant_approved_at         timestamptz,
  bank_review_reason           varchar(64),
  approved_by                  varchar(64),
  approved_at                  timestamptz,
  rejection_reason             varchar(255),
  wallet_transaction_id        uuid,
  completed_at                 timestamptz,
  failure_reason               varchar(255),
  idempotency_key              varchar(128) NOT NULL,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_merchant_refund_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE merchant_refund IS 'A full or partial refund of a merchant payment';
COMMENT ON COLUMN merchant_refund.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN merchant_refund.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN merchant_refund.created_at IS 'Creation time';
COMMENT ON COLUMN merchant_refund.created_by IS 'Principal that created the row';
COMMENT ON COLUMN merchant_refund.updated_at IS 'Last update time';
COMMENT ON COLUMN merchant_refund.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN merchant_refund.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN merchant_refund.merchant_id IS 'Merchant';
COMMENT ON COLUMN merchant_refund.original_transaction_id IS 'Payment refunded';
COMMENT ON COLUMN merchant_refund.amount IS 'Refund amount';
COMMENT ON COLUMN merchant_refund.currency IS 'Currency';
COMMENT ON COLUMN merchant_refund.reason IS 'Reason';
COMMENT ON COLUMN merchant_refund.status IS 'REQUESTED -> COMPLETED (or PENDING_BANK_APPROVAL after the merchant''s own approval when the bank reviews it) -> COMPLETED; REJECTED, FAILED';
COMMENT ON COLUMN merchant_refund.merchant_approved_by IS 'Merchant-side approver (merchant app four-eyes) when the bank''s checkers review the refund';
COMMENT ON COLUMN merchant_refund.merchant_approved_at IS 'Merchant-side approval time';
COMMENT ON COLUMN merchant_refund.bank_review_reason IS 'Why the bank''s checkers review the refund in central approvals (AMOUNT_THRESHOLD, MERCHANT_RISK)';
COMMENT ON COLUMN merchant_refund.approved_by IS 'Approver';
COMMENT ON COLUMN merchant_refund.approved_at IS 'Approval time';
COMMENT ON COLUMN merchant_refund.rejection_reason IS 'Rejection reason';
COMMENT ON COLUMN merchant_refund.wallet_transaction_id IS 'Refund transaction';
COMMENT ON COLUMN merchant_refund.completed_at IS 'Completion time';
COMMENT ON COLUMN merchant_refund.failure_reason IS 'Failure reason';
COMMENT ON COLUMN merchant_refund.idempotency_key IS 'Client key';
COMMENT ON COLUMN merchant_refund.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_refund.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_refund.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_refund.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN merchant_refund.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_merchant_refund_tenant ON merchant_refund (tenant_id, created_at);
CREATE INDEX ix_merchant_refund_merchant_id ON merchant_refund (merchant_id);
CREATE INDEX ix_merchant_refund_original_transaction_id ON merchant_refund (original_transaction_id);
CREATE INDEX ix_merchant_refund_wallet_transaction_id ON merchant_refund (wallet_transaction_id);
ALTER TABLE merchant_refund ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON merchant_refund USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_merchant_refund_touch BEFORE UPDATE ON merchant_refund FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium); relayed rows stay for the replay window.
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  published_at    timestamptz
);
COMMENT ON COLUMN outbox.published_at IS 'When the relay published the event (NULL = pending). Relayed rows are kept for the replay window (meridian.events.retention.window) and then purged (MR-GAME-DAY)';
CREATE INDEX ix_outbox_pending ON outbox (created_at, id) WHERE published_at IS NULL;
CREATE INDEX ix_outbox_published ON outbox (published_at) WHERE published_at IS NOT NULL;
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA merchant TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA merchant TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA merchant GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
